360→      prefix: '/',
361→      noCache: process.env.NODE_ENV === 'development', // Disable cache in dev
362→    }));
363→
364→    // SPA fallback routes for client-side routing
365→    // These catch paths like /tasks, /items, /inbox that don't have static files
366→    const spaRoutes = [
367→      '/tasks', '/tasks/*',
368→      '/items', '/items/*',
369→      '/inbox',
370→      '/observations',
371→      '/triage',
372→      '/validate',
373→      '/sessions', '/sessions/*',
374→      '/agents',
375→      '/specs',
376→      '/workflows',
377→      '/plans',
378→      '/settings',
379→    ];
