386→
387→  // AC-1, AC-2: Start server on localhost only
388→  // Using 'localhost' hostname allows Bun/OS to bind to both 127.0.0.1 and ::1
389→  app.listen({
390→    port,
391→    hostname: 'localhost', // Resolves to both IPv4 and IPv6 loopback
392→  });
393→
394→  console.log(`[daemon] Server listening on http://localhost:${port} (IPv4: 127.0.0.1, IPv6: ::1)`);
395→  console.log(`[daemon] WebSocket available at ws://localhost:${port}/ws`);
396→
397→  // AC: @agent-dispatch-engine ac-5 - Wire file change callback to dispatch engine
398→  projectContextManager.setFileChangeCallback((projectPath, file) => {
399→    // Only forward changes to project.tasks.yaml
400→    if (!file.endsWith('project.tasks.yaml')) return;
401→    const engine = getDispatchEngine(projectPath);
402→    if (engine) {
403→      engine.handleFileChange(projectPath).catch((err) => {
404→        console.error('[dispatch] Error handling file change:', err);
405→      });
406→    }
407→  });
408→
409→  // AC: @multi-directory-daemon ac-17 - Start file watcher for startup project
410→  if (startupProjectPath) {
411→    try {
412→      await projectContextManager.startWatcher(startupProjectPath);
413→      console.log(`[daemon] File watcher started for startup project: ${startupProjectPath}`);
414→    } catch (error) {
415→      console.error('[daemon] Failed to start file watcher for startup project:', error);
416→    }
417→  }
418→
419→  // AC: @daemon-server ac-13, ac-14 - Start heartbeat monitoring
420→  heartbeatManager.start(pubsubManager.getAllConnections());
421→
422→  // AC-12: Graceful shutdown on SIGTERM/SIGINT
423→  const shutdown = async (signal: string) => {
424→    console.log(`[daemon] Received ${signal}, shutting down gracefully...`);
425→
426→    try {
427→      // Stop heartbeat monitoring
428→      heartbeatManager.stop();
429→
430→      // AC: @agent-dispatch-engine ac-11 - Stop all dispatch engines before shutting down
431→      await stopAllEngines();
432→
433→      // AC: @multi-directory-daemon ac-11b - Stop all file watchers
434→      await projectContextManager.stopAllWatchers();
435→      console.log('[daemon] All file watchers stopped');
436→
437→      // Close all WebSocket connections with code 1000 (clean close)
438→      // AC: @trait-websocket-protocol ac-7
439→      for (const [sessionId, ws] of pubsubManager.getAllConnections()) {
440→        ws.close(1000, 'Server shutting down');
441→      }
442→
443→      // Stop the server
444→      await app.server?.stop();
445→
446→      // AC: @daemon-server ac-10 - Remove PID file on shutdown
447→      if (isDaemon) {
448→        pidManager.remove();
449→        console.log('[daemon] PID file removed');
450→      }
451→
452→      console.log('[daemon] Server stopped successfully');
453→      process.exit(0);
454→    } catch (error) {
455→      console.error('[daemon] Error during shutdown:', error);
456→      process.exit(1);
457→    }
458→  };
459→
460→  process.on('SIGTERM', () => shutdown('SIGTERM'));
461→  process.on('SIGINT', () => shutdown('SIGINT'));
462→
463→  return app;
464→}
